package com.garmin.fit.repair

import com.garmin.fit.Decode
import com.garmin.fit.FileEncoder
import com.garmin.fit.Fit
import java.io.File
import java.io.FileInputStream
import java.io.IOException

class ActivityRepairTool {
    private var inputFilePath: String? = null

    /**
     * @return the path to the output file
     */
    var outputFilePath: String? = null
        private set
    private var fileEncoder: FileEncoder? = FileEncoder()
    private var inputFileStream: FileInputStream? = null

    constructor(inputFilePath: String?) {
        this.inputFilePath = inputFilePath
        outputFilePath = createOutputFilePath()
    }

    /**
     * Repairs a corrupt or invalid FIT Activity file if possible
     */
    fun repair() {
        val activityRepairFilter = ActivityRepairFilter()

        try {
            inputFileStream = FileInputStream(inputFilePath)

            val decoder = Decode()
            decoder.addListener(activityRepairFilter)
            decoder.read(inputFileStream!!)
        } catch (e: Exception) {
            println("Error while decoding file. Attempting to repair file...")
        } finally {
            closeInputStream()
        }

        if (!activityRepairFilter.canRepairFile()) {
            println("File can not be repaired.")
            return
        }

        try {
            val outputFile = File(outputFilePath)
            outputFile.delete()

            fileEncoder = FileEncoder(outputFile, Fit.ProtocolVersion.V2_0)

            activityRepairFilter.addListener(fileEncoder!!)

            activityRepairFilter.flushMesgs()
        } catch (e: Exception) {
            println("Error in repair.\n")
        } finally {
            closeFileEncoder()

            println("Repair complete. Repaired .fit file can be found at: $outputFilePath")
        }
    }

    private fun createOutputFilePath(): String {
        return (inputFilePath!!.substring(0, (inputFilePath!!.length - 4))
                + "_repaired.fit")
    }

    private fun closeInputStream() {
        try {
            inputFileStream!!.close()
        } catch (e: IOException) {
            System.err.println("Error closing Input File Stream.")
        }
    }

    private fun closeFileEncoder() {
        try {
            if (fileEncoder != null) {
                fileEncoder!!.close()
            }
        } catch (e: Exception) {
            System.err.println("Error closing File Encoder.")
        }
    }
}

@Throws(IOException::class)
fun main(args: Array<String>) {
    if (!validateCommandlineArgs(args)) {
        printUsage()
        return
    }

    val file = File(args[0])
    if (!file.exists()) {
        println("Input file does not exist: " + args[0])
        return
    }
    if (!file.name.lowercase().endsWith(".fit")) {
        println("Input file is not a .fit file: " + args[0])
        return
    }

    val activityRepairTool = ActivityRepairTool(args[0])
    activityRepairTool.repair()
}

private fun validateCommandlineArgs(args: Array<String>): Boolean {
    return args.size == 1
}

private fun printUsage() {
    println("Usage: java -jar ActivityRepairTool.jar <filename>")
}
